contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, string calldata description) public payable {
        require(caller != address(this), "precondition: caller must not be the test contract");
        require(caller != c.jojoTeam(), "precondition: caller must be a non-team address");

        bool reverted;
        bool success; c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) { success = false; } else { success = true; }
        reverted = !success;

        assert(reverted);
    }

    receive() external payable {}
}

